import{_ as a,o as e,c as i,a2 as l}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"TUI 탐색기","description":"","frontmatter":{},"headers":[],"relativePath":"ko/advanced/tui.md","filePath":"ko/advanced/tui.md","lastUpdated":1784903584000}'),o={name:"ko/advanced/tui.md"};function d(r,t,s,n,c,h){return e(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="tui-탐색기" tabindex="-1">TUI 탐색기 <a class="header-anchor" href="#tui-탐색기" aria-label="Permalink to &quot;TUI 탐색기&quot;">​</a></h1><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>swag2mcp에는 대화형 API 탐색을 위한 내장 TUI(터미널 사용자 인터페이스)가 포함되어 있습니다. 터미널을 떠나지 않고 API 엔드포인트를 검색, 탐색, 검사, 호출할 수 있는 전체 화면 터미널 애플리케이션입니다.</p><h2 id="실행" tabindex="-1">실행 <a class="header-anchor" href="#실행" aria-label="Permalink to &quot;실행&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p>설정 파일이 없으면 TUI가 자동으로 초기화 마법사를 먼저 시작합니다.</p><h2 id="모드" tabindex="-1">모드 <a class="header-anchor" href="#모드" aria-label="Permalink to &quot;모드&quot;">​</a></h2><p>TUI는 세 가지 모드가 있으며 <code>Tab</code> 키로 전환할 수 있습니다:</p><h3 id="검색-모드" tabindex="-1">검색 모드 <a class="header-anchor" href="#검색-모드" aria-label="Permalink to &quot;검색 모드&quot;">​</a></h3><p>모든 spec의 모든 엔드포인트에 대한 전문 검색입니다. <code>search</code> MCP 도구와 동일한 쿼리 구문을 지원합니다.</p><ul><li>쿼리를 입력하여 엔드포인트 이름, 경로, 설명 검색</li><li>메서드, 태그 또는 경로로 결과 필터링</li><li>한 번의 키 입력으로 엔드포인트 세부 정보 보기</li><li>페이지네이션으로 결과 탐색 (페이지당 10개 항목)</li></ul><h3 id="탐색-모드" tabindex="-1">탐색 모드 <a class="header-anchor" href="#탐색-모드" aria-label="Permalink to &quot;탐색 모드&quot;">​</a></h3><p>Spec 계층 구조를 통한 트리 탐색:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Spec → Collection → Tag → Endpoint</span></span></code></pre></div><ul><li>트리를 따라 내려가 특정 엔드포인트 찾기</li><li>엔드포인트 세부 정보 보기 (매개변수, 요청 본문, 응답)</li><li>TUI에서 직접 API 호출</li><li>엔드포인트 세부 정보를 JSON 파일로 저장</li></ul><h3 id="인증-모드" tabindex="-1">인증 모드 <a class="header-anchor" href="#인증-모드" aria-label="Permalink to &quot;인증 모드&quot;">​</a></h3><p>모든 spec의 인증 토큰과 헤더를 봅니다. 디버깅 또는 curl 명령어 생성에 유용합니다.</p><h2 id="컨트롤" tabindex="-1">컨트롤 <a class="header-anchor" href="#컨트롤" aria-label="Permalink to &quot;컨트롤&quot;">​</a></h2><table tabindex="0"><thead><tr><th>키</th><th>동작</th></tr></thead><tbody><tr><td><code>↑</code> / <code>↓</code></td><td>위/아래 이동</td></tr><tr><td><code>Enter</code></td><td>선택 또는 열기</td></tr><tr><td><code>Esc</code></td><td>한 단계 뒤로</td></tr><tr><td><code>Tab</code></td><td>검색, 탐색, 인증 모드 간 전환</td></tr><tr><td><code>/</code></td><td>검색 입력 포커스</td></tr><tr><td><code>N</code> / <code>P</code></td><td>다음 / 이전 페이지</td></tr><tr><td><code>B</code></td><td>이전 화면으로</td></tr><tr><td><code>M</code></td><td>메인 메뉴로</td></tr><tr><td><code>S</code></td><td>엔드포인트 세부 정보를 JSON 파일로 저장</td></tr><tr><td><code>q</code> / <code>Ctrl+C</code></td><td>종료</td></tr></tbody></table><h2 id="상태" tabindex="-1">상태 <a class="header-anchor" href="#상태" aria-label="Permalink to &quot;상태&quot;">​</a></h2><p>TUI는 탐색하면서 다음 상태를 거칩니다:</p><ol><li><strong>로딩</strong> — 워크스페이스에서 데이터 로드 중</li><li><strong>검색</strong> — 쿼리 입력이 있는 검색 모드</li><li><strong>탐색</strong> — spec 목록이 있는 탐색 모드</li><li><strong>Spec 목록</strong> — 모든 spec 목록</li><li><strong>Collection 목록</strong> — spec 내의 collection</li><li><strong>Tag 목록</strong> — collection 내의 태그</li><li><strong>Endpoint 목록</strong> — 태그 내의 엔드포인트</li><li><strong>Endpoint 상세</strong> — 전체 엔드포인트 정보</li><li><strong>호출 결과</strong> — API 호출 결과</li><li><strong>오류</strong> — 메시지가 있는 오류 상태</li></ol><h2 id="엔드포인트-상세-보기" tabindex="-1">엔드포인트 상세 보기 <a class="header-anchor" href="#엔드포인트-상세-보기" aria-label="Permalink to &quot;엔드포인트 상세 보기&quot;">​</a></h2><p>엔드포인트를 선택하면 TUI가 다음을 표시합니다:</p><ul><li>HTTP 메서드 및 경로</li><li>Base URL 및 전체 URL</li><li>요약 및 설명</li><li>모든 매개변수 (이름, 위치, 타입, 필수)</li><li>요청 본문 스키마 (해당하는 경우)</li><li>응답 코드 및 스키마</li><li>폐기 상태</li></ul><h2 id="요구-사항" tabindex="-1">요구 사항 <a class="header-anchor" href="#요구-사항" aria-label="Permalink to &quot;요구 사항&quot;">​</a></h2><ul><li><strong>터미널 크기:</strong> 최소 80×24 문자</li><li><strong>터미널 에뮬레이터:</strong> 대부분의 최신 터미널에서 작동 (iTerm2, Terminal.app, GNOME Terminal, Windows Terminal 등)</li><li><strong>SSH:</strong> SSH 연결을 통해 작동</li></ul><h2 id="중요-참고-사항" tabindex="-1">중요 참고 사항 <a class="header-anchor" href="#중요-참고-사항" aria-label="Permalink to &quot;중요 참고 사항&quot;">​</a></h2><ul><li><strong>자동 초기화</strong> — 설정 파일이 없으면 TUI가 자동으로 초기화 마법사를 시작합니다</li><li><strong>페이지네이션</strong> — 목록은 페이지당 10개 항목으로 페이지네이션됩니다. <code>N</code>과 <code>P</code>로 탐색하세요</li><li><strong>엔드포인트 세부 정보 저장</strong> — 엔드포인트 상세 보기에서 <code>S</code>를 눌러 전체 세부 정보를 현재 디렉토리에 JSON 파일로 저장하세요</li><li><strong>인증 모드</strong> — 디버깅을 위한 토큰 및 헤더 표시. 프로덕션에서는 <code>--disable-llm-auth</code>로 인증 도구를 비활성화할 수 있습니다</li></ul>',29)])])}const g=a(o,[["render",d]]);export{u as __pageData,g as default};
